function [predictedLabel, testLabel] = testTabICL()
% Load the test predictions generated by the Python TabICLv2 run.
here = fileparts(mfilename('fullpath'));
f = fullfile(here, 'Results', 'PredictionResults_TabICL.mat');
assert(isfile(f), 'Prediction file not found. Run trainTabICL.py first.');
R = load(f);
predictedLabel = R.predictedLabel;
testLabel = R.testLabel;
assert(numel(predictedLabel) == numel(testLabel), ...
    'Prediction and ground-truth counts do not match.');
fprintf('Loaded %d TabICLv2 predictions.\n', numel(predictedLabel));
end
